@media (max-width:860px){.wsalpakacrew__kar{grid-auto-columns:82%}.wsalpakacrew__pus--l{left:4px}.wsalpakacrew__pus--d{right:4px}}
@media (max-width:860px){.wsalpakacrew__s{padding:38px 0}.wsalpakacrew__dva{grid-template-columns:1fr;gap:22px}.wsalpakacrew__dva--rev>div:first-child{order:0}
.wsalpakacrew__sred{grid-template-columns:1fr;gap:22px}.wsalpakacrew__sm{max-width:300px;margin:0 auto;order:-1}.wsalpakacrew__g3,.wsalpakacrew__g4,.wsalpakacrew__g5{grid-template-columns:1fr 1fr}.wsalpakacrew__red4{grid-template-columns:1fr 1fr}.wsalpakacrew__plavo{margin-top:-38px}}
@media (max-width:560px){.wsalpakacrew__g2,.wsalpakacrew__g3,.wsalpakacrew__g4{grid-template-columns:1fr}}
/* dizajn.py */
.wsalpakacrew__s{padding:72px 0}.wsalpakacrew__s.wsalpakacrew__s--bg{background:#d7dedc}.wsalpakacrew__s.wsalpakacrew__traka{padding:40px 0}.wsalpakacrew__s.wsalpakacrew__traka:not(.wsalpakacrew__s--bg){background:#fff}
.wsalpakacrew__kicker{color:#073026;letter-spacing:1.8px;font-size:12.5px}.wsalpakacrew__kicker::before{content:"";display:inline-block;width:22px;height:2px;background:#073026;vertical-align:middle;margin:-2px 10px 0 0;border-radius:2px}
.wsalpakacrew__h2 em{color:#073026}.wsalpakacrew__dva .wsalpakacrew__zak{border-left:3px solid #073026;padding-left:14px}
.wsalpakacrew__media,.wsalpakacrew__polna{box-shadow:0 14px 34px rgba(7,48,38,.22);border:1px solid rgba(7,48,38,.25)}
.wsalpakacrew__k{border:1px solid rgba(7,48,38,.35);border-radius:16px;box-shadow:0 6px 18px rgba(0,0,0,.05);transition:transform .2s,box-shadow .2s}.wsalpakacrew__k:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(7,48,38,.22)}
.wsalpakacrew__pog>div{border:1px solid rgba(7,48,38,.35);border-radius:16px;padding:28px 18px;transition:transform .2s,box-shadow .2s}.wsalpakacrew__pog>div:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(7,48,38,.22)}
span.wsalpakacrew__pi{opacity:1;width:58px;height:58px;border-radius:50%;background:#b5c1be;border:1px solid #073026;color:#073026;display:flex;align-items:center;justify-content:center;margin:0 auto 14px}.wsalpakacrew__pi svg{width:28px;height:28px}
.wsalpakacrew__red4:not(.wsalpakacrew__pog)>div{background:#fff;border:1px solid rgba(7,48,38,.35);border-radius:16px;padding:24px 16px;box-shadow:0 6px 18px rgba(0,0,0,.05)}.wsalpakacrew__red3 span.wsalpakacrew__pi{width:44px;height:44px;margin-bottom:8px}.wsalpakacrew__red3 .wsalpakacrew__pi svg{width:22px;height:22px}.wsalpakacrew__red3>div{border-color:rgba(7,48,38,.35)}
.wsalpakacrew__pog strong{color:#1c1c1c}.wsalpakacrew__st,.wsalpakacrew__kv li::before{background:#073026}.wsalpakacrew__tab th{background:#073026!important}
.wsalpakacrew__ti{background:linear-gradient(135deg,#073026,#3e5e56);box-shadow:0 6px 14px rgba(7,48,38,.30)}.wsalpakacrew__tk{border-color:rgba(7,48,38,.30)}
.wsalpakacrew__ime{display:flex;align-items:center;gap:10px}.wsalpakacrew__av{flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:#b5c1be;border:1px solid #073026;color:#073026;font-style:normal;font-weight:800;font-size:14px;display:inline-flex;align-items:center;justify-content:center}
div.wsalpakacrew__pog{text-align:center;border:1px solid rgba(7,48,38,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wsalpakacrew__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(7,48,38,.22)}div.wsalpakacrew__pog>strong,div.wsalpakacrew__pog>span:not(.wsalpakacrew__pi){display:block}
.wsalpakacrew__k--ik .wsalpakacrew__kt{text-align:center;padding:28px 20px}
.wsalpakacrew__pus{color:#073026}.wsalpakacrew__plavo{background:#073026;margin-top:-72px}.wsalpakacrew__k--temna{background:#073026}
@media (max-width:860px){.wsalpakacrew__s{padding:46px 0}.wsalpakacrew__s.wsalpakacrew__traka{padding:30px 0}.wsalpakacrew__plavo{margin-top:-46px}.wsalpakacrew__pog>div{padding:22px 12px}}
@media (max-width:767px){.wsalpakacrew__v{padding:0 16px}}
/* /dizajn.py */
.wsalpakacrew__v>.wsalpakacrew__zak{text-align:center}
.wsalpakacrew__dva>*{min-width:0}
.wsalpakacrew__tw{overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%}
@media (max-width:767px){.wsalpakacrew__tab{font-size:13px;min-width:460px}.wsalpakacrew__tab th,.wsalpakacrew__tab td{padding:9px 8px}}
</style>
<script>
(function(){document.querySelectorAll('.wsalpakacrew__kar').forEach(function(k){
  var w=document.createElement('div');w.className='wsalpakacrew__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wsalpakacrew__pus wsalpakacrew__pus--'+s;b.setAttribute('aria-label',s==='l'?'Prethodno':'Sljedeće');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
    b.addEventListener('click',function(){var x=k.firstElementChild;var d=x?x.getBoundingClientRect().width+22:300;k.scrollBy({left:s==='l'?-d:d,behavior:'smooth'});});w.appendChild(b);});
});})();
</script>
